import math
def interp(points, x):
 p=sorted(points)
 for i in range(len(p)-1):
  if p[i][0]<=x<=p[i+1][0]:
   a,b=p[i],p[i+1]; return a[1]+(b[1]-a[1])*(x-a[0])/max(0.001,b[0]-a[0])
 return None
def control(o):
 m=o['local_map']; l=m['left_rail']; r=m['right_rail']
 vals=[]
 for x in (3,5,7):
  a=interp(l,x); b=interp(r,x)
  if a is not None and b is not None: vals.append((a+b)/2)
 target=sum(vals)/len(vals) if vals else 0
 desired=max(-18,min(18,-target*3.0))
 hitch=o['hitch_deg']
 steer=max(-35,min(35,2.0*(hitch-desired)))
 return steer,-0.8

