import math
def control(obs):
    m=obs['local_map']
    def interp(points,x):
        p=sorted(points)
        for a,b in zip(p,p[1:]):
            if a[0]<=x<=b[0] and b[0]>a[0]:
                return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
        return None
    vals=[]
    for x in (5,8,11,14):
        l=interp(m['left_rail'],x); r=interp(m['right_rail'],x)
        if l is not None and r is not None: vals.append((x,(l+r)/2))
    target=0
    if vals:
        x,y=vals[-1]
        target=max(-18,min(18,math.degrees(math.atan2(y,x))*1.5))
    h=obs['hitch_deg']
    steer=max(-35,min(35,2.0*(h-target)))
    return (steer,-1.0)

